// RunResumeInteractive executes the resume command with a pty, allowing
// interactive prompt responses. The input string is sent to the process
// after a brief delay to allow the prompt to appear.
func (env *TestEnv) RunResumeInteractive(branchName, input string) (string, error) {
	env.T.Helper()

	cmd := exec.Command(getTestBinary(), "resume", branchName)
	cmd.Dir = env.RepoDir
	cmd.Env = append(os.Environ(),
		"ENTIRE_TEST_CLAUDE_PROJECT_DIR="+env.ClaudeProjectDir,
		"TERM=xterm", // Ensure huh thinks it has a proper terminal
	)

	// Start command with a pty
	ptmx, err := pty.Start(cmd)
	if err != nil {
		return "", fmt.Errorf("failed to start pty: %w", err)
	}
	defer ptmx.Close()

	// Read output in a goroutine
	var output bytes.Buffer
	done := make(chan error, 1)
	go func() {
		_, err := io.Copy(&output, ptmx)
		done <- err
	}()

	// Give the process time to show the prompt, then send input
	time.Sleep(500 * time.Millisecond)
	if _, err := ptmx.WriteString(input); err != nil {
		// Ignore write errors - process may have already exited
		env.T.Logf("Note: write to pty returned: %v", err)
	}

	// Wait for process to complete
	cmdErr := cmd.Wait()

	// Wait for output reader to finish (with timeout)
	select {
	case <-done:
	case <-time.After(2 * time.Second):
	}

	return output.String(), cmdErr
}

