// RunResumeInteractive executes the resume command with a pty, allowing
// interactive prompt responses. The respond function receives the pty for
// reading output and writing input. Timeouts and cleanup are managed centrally.
func (env *TestEnv) RunResumeInteractive(branchName string, respond func(ptyFile *os.File)) (string, error) {
	env.T.Helper()

	cmd := exec.Command(getTestBinary(), "resume", branchName)
	cmd.Dir = env.RepoDir
	cmd.Env = append(os.Environ(),
		"ENTIRE_TEST_CLAUDE_PROJECT_DIR="+env.ClaudeProjectDir,
		"TERM=xterm",
	)

	// Start command with a pty
	ptmx, err := pty.Start(cmd)
	if err != nil {
		return "", fmt.Errorf("failed to start pty: %w", err)
	}
	defer ptmx.Close()

	// Capture all output in background
	var output bytes.Buffer
	outputDone := make(chan struct{})
	go func() {
		defer close(outputDone)
		_, _ = io.Copy(&output, ptmx)
	}()

	// Let the respond function interact with the pty
	// It runs with a timeout to prevent hanging tests
	respondDone := make(chan struct{})
	go func() {
		defer close(respondDone)
		respond(ptmx)
	}()

	// Wait for respond function with timeout
	select {
	case <-respondDone:
		// respond completed
	case <-time.After(10 * time.Second):
		env.T.Log("Warning: respond function timed out")
	}

	// Wait for process to complete with timeout
	cmdDone := make(chan error, 1)
	go func() {
		cmdDone <- cmd.Wait()
	}()

	var cmdErr error
	select {
	case cmdErr = <-cmdDone:
		// process completed
	case <-time.After(10 * time.Second):
		_ = cmd.Process.Kill()
		cmdErr = fmt.Errorf("process timed out")
	}

	// Give output goroutine time to finish after process exits
	select {
	case <-outputDone:
	case <-time.After(1 * time.Second):
	}

	return output.String(), cmdErr
}

